CA={  # cat body archetypes
 'cobby':dict(bodyw=1.18,legw=1.12,leg=.88,snout=.7,head=1.05,ear=.85,tail=.85),
 'foreign':dict(bodyw=.82,legw=.8,leg=1.12,ear=1.35,snout=1.2,tail=1.2,neck=1.15),
 'long':dict(fluff=1.35,tailw=1.6),
 'semilong':dict(fluff=1.18,tailw=1.35),
 'flat':dict(snout=.38,snoutw=1.15,ear=.75,head=1.1),
}
def K(key,name,m,arch,pat,cols,**sh):
    S={}
    for a in arch.split():
        for k,v in CA[a].items(): S[k]=S.get(k,1)*v if k not in('drop','dropf','curl','tailup') else v
    S.update(sh)
    return dict(key=key,name=name,grp='cats',type='CAT',base='cat',m=m,sh=S,pat=pat,cols=cols)
def Q(c,b=None,mk=None,eye=None,**o):
    d=dict(coat=c,belly=b or c);
    if mk: d['mark']=mk
    if eye: d['eye']=eye
    d.update(o); return d
